import json
import docx

def generate_offer():
    # Load data
    with open('employee_data.json', 'r') as f:
        data = json.load(f)

    doc = docx.Document('offer_letter_template.docx')

    # Prepare replacements
    replacements = {f"{{{{{key}}}}}": val for key, val in data.items()}

    # Handle Relocation Logic
    relocation_needed = data.get("RELOCATION_PACKAGE", "No") == "Yes"

    # We iterate over a list of paragraphs to allow modifying them safely
    for para in doc.paragraphs:
        # Check for conditional block markers in the paragraph text
        if "{{IF_RELOCATION}}" in para.text:
            if relocation_needed:
                # Remove markers, keep content
                # We need to be careful with runs. 
                # Since we saw in inspection that markers were in their own runs or at start/end, 
                # we can try string replacement on runs.
                for run in para.runs:
                    run.text = run.text.replace("{{IF_RELOCATION}}", "")
                    run.text = run.text.replace("{{END_IF_RELOCATION}}", "")
            else:
                # Remove the entire content of the paragraph
                # Clearing all runs
                for run in para.runs:
                    run.text = ""
                # Also clear the paragraph text just in case
                para.text = ""

    # Global replacement for variables
    # We do this after handling the conditional blocks so we can fill in {{RELOCATION_AMOUNT}} etc 
    # if they were preserved.

    for para in doc.paragraphs:
        for run in para.runs:
            for key, val in replacements.items():
                if key in run.text:
                    run.text = run.text.replace(key, str(val))

    # Also need to handle tables if any (offer letters might have tables)
    for table in doc.tables:
        for row in table.rows:
            for cell in row.cells:
                for paragraph in cell.paragraphs:
                     for run in paragraph.runs:
                        for key, val in replacements.items():
                            if key in run.text:
                                run.text = run.text.replace(key, str(val))

    doc.save('/root/offer_letter_filled.docx')

if __name__ == "__main__":
    generate_offer()
